#include "exgine/physics.hpp"
#include <cassert>
#include <cmath>
namespace { exgine::PhysicsColliderDesc box(){exgine::PhysicsColliderDesc c;c.shape.type=exgine::PhysicsShapeType::Box;c.shape.data=exgine::PhysicsBoxShape{{.5f,.5f,.5f}};c.material.restitution=0;c.material.dynamic_friction=.5f;return c;} }
int main(){exgine::PhysicsWorldSettings s;s.fixed_timestep=1.0f/120.0f;s.max_substeps=16;exgine::PhysicsWorld w(s);assert(w.settings().valid());exgine::PhysicsRigidBodyDesc floor_desc;floor_desc.type=exgine::PhysicsBodyType::Static;floor_desc.transform.position={0,-.5f,0};floor_desc.flags=static_cast<exgine::PhysicsBodyFlags>(exgine::PhysicsBodyFlag::AllowSleep);const auto floor=w.create_body(floor_desc);assert(floor);auto fc=box();fc.shape.data=exgine::PhysicsBoxShape{{5,.5f,5}};assert(w.add_collider(floor,fc));exgine::PhysicsRigidBodyDesc body_desc;body_desc.type=exgine::PhysicsBodyType::Dynamic;body_desc.transform.position={0,3,0};const auto body=w.create_body(body_desc);assert(body);assert(w.add_collider(body,box()));assert(w.step(.5f).substeps>0);const auto t=w.body_transform(body);assert(t&&std::isfinite(t->position.y)&&t->position.y<3);assert(w.stats().bodies==2&&w.stats().colliders==2);const auto hits=w.raycast({{0,5,0},{0,-1,0},20});assert(!hits.empty()&&hits.front().valid());const auto overlaps=w.overlap(exgine::PhysicsShape{exgine::PhysicsShapeType::Sphere,exgine::PhysicsSphereShape{1}},{{0,0,0},{0,0,0}});assert(!overlaps.empty());bool began=false;w.set_callbacks({[&](const exgine::PhysicsContactEvent&e){if(e.type==exgine::PhysicsContactEvent::Type::Begin||e.type==exgine::PhysicsContactEvent::Type::Persist)began=true;},{},{},{}});for(int i=0;i<120;++i)w.step(1.0f/120.0f);assert(began);exgine::PhysicsRigidBodyDesc second=body_desc;second.transform.position={2,3,0};const auto b=w.create_body(second);assert(b);exgine::PhysicsConstraintDesc d;d.type=exgine::PhysicsConstraintType::Distance;d.body_a=body;d.body_b=b;d.linear_limits[0].enabled=true;d.linear_limits[0].lower=2;d.linear_limits[0].upper=2;d.stiffness=1;assert(w.add_constraint(d));assert(w.set_linear_velocity(b,{-10,0,0}));for(int i=0;i<10;++i)w.step(1.0f/120.0f);assert(w.has_constraint(1));assert(w.destroy_body(b)&&!w.has_body(b));w.clear();assert(w.stats().bodies==0&&w.stats().colliders==0&&w.stats().constraints==0);return 0;}
